def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Most frequent color is the background.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Find the uniform full-length line that is not the background.
    sep = None
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != bg:
            sep = ("row", r, grid[r][0])
            break
    if sep is None:
        for c in range(w):
            vals = {grid[r][c] for r in range(h)}
            if len(vals) == 1 and grid[0][c] != bg:
                sep = ("col", c, grid[0][c])
                break
    if sep is None:
        return out

    obj = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] != bg and grid[r][c] != sep[2]]
    if not obj:
        return out

    if sep[0] == "row":
        s = sep[1]
        lo = min(r for r, c in obj)
        hi = max(r for r, c in obj)
        if hi < s:  # object above separator
            shift = s - 1 - hi
            stripe = lo + shift - 1
        else:       # object below separator
            shift = s + 1 - lo
            stripe = hi + shift + 1
        moved = [(r + shift, c) for r, c in obj]
        for r, c in obj:
            out[r][c] = bg
        for r, c in moved:
            out[r][c] = grid[r - shift][c]
        if 0 <= stripe < h:
            out[stripe] = [8] * w
    else:
        s = sep[1]
        lo = min(c for r, c in obj)
        hi = max(c for r, c in obj)
        if hi < s:  # object left of separator
            shift = s - 1 - hi
            stripe = lo + shift - 1
        else:       # object right of separator
            shift = s + 1 - lo
            stripe = hi + shift + 1
        moved = [(r, c + shift) for r, c in obj]
        for r, c in obj:
            out[r][c] = bg
        for r, c in moved:
            out[r][c] = grid[r][c - shift]
        if 0 <= stripe < w:
            for r in range(h):
                out[r][stripe] = 8

    return out
